    configureDevOnlyElement(element) {
        if (!element) return;
        if (this.isDevMode) {
            element.removeAttribute('hidden');
        } else {
            element.setAttribute('hidden', 'true');
        }
    }

    updateAuthSurface(user) {
        if (!this.authBindings) return;
        const signedIn = Boolean(user);

        if (this.authBindings.authBtn) {
            this.authBindings.authBtn.textContent = signedIn ? 'Sign out' : 'Sign in with Google';
            this.authBindings.authBtn.disabled = false;
        }

        if (signedIn) {
            const label = user?.name || user?.email || 'your Google account';
            this.setAuthStatusMessage(`Signed in as ${label}`);
        } else if (this.authBindings.authStatus && !this.authBindings.authStatus.classList.contains('has-error')) {
            this.setAuthStatusMessage('Signed out');
        }
    }

    setAuthStatusMessage(message, isError = false) {
        if (!this.authBindings?.authStatus) return;
        this.authBindings.authStatus.textContent = message;
        if (isError) {
            this.authBindings.authStatus.classList.add('has-error');
        } else {
            this.authBindings.authStatus.classList.remove('has-error');
        }
    }

    handleGoogleSignIn() {
        if (!this.authManager || !this.authBindings?.authBtn) return;

        this.setButtonBusy(this.authBindings.authBtn, true, 'Redirecting...');
        try {
            this.setAuthStatusMessage('Redirecting to Google...');
            this.authManager.signIn();
        } catch (err) {
            console.warn('Google sign-in failed', err);
            this.setAuthStatusMessage(err?.message || 'Unable to sign in with Google.', true);
            this.setButtonBusy(this.authBindings.authBtn, false);
        }
    }

    async handleGoogleSignOut(showBusy = false) {
        if (!this.authManager) return;
        const button = showBusy ? this.authBindings?.authBtn : null;

        if (button) {
            this.setButtonBusy(button, true, 'Signing out...');
        }

        this.authManager.signOut();
        if (this.supabaseRelay) {
            await this.supabaseRelay.clearSession();
        }
        this.setAuthStatusMessage('Signed out');
        if (button) {
            this.setButtonBusy(button, false);
        }
        this.updateAuthSurface(this.authManager.getUser());
    }

    async handlePlanCheckout() {
        if (!this.subscriptionManager || !this.authBindings?.subscribeBtn) return;

        this.setButtonBusy(this.authBindings.subscribeBtn, true, 'Preparing checkout...');
        try {
            await this.subscriptionManager.startCheckout('interview-assistant');
        } catch (err) {
            console.warn('Checkout placeholder failed', err);
            this.renderSubscriptionState({
                status: 'error',
                message: err?.message || 'Unable to start checkout.'
            });
            if (err?.code === 'AUTH_REQUIRED') {
                this.setAuthStatusMessage(this.subscriptionManager.authRequiredMessage, true);
            }
        } finally {
            this.setButtonBusy(this.authBindings.subscribeBtn, false);
        }
    }

    renderSupabaseState(state) {
        if (!state) return;
        this.supabaseState = state;
        if (this.authBindings?.supabaseStatus) {
            this.authBindings.supabaseStatus.textContent = state.message;
        }
    }

    renderSubscriptionState(state) {
        if (!state) return;
        this.subscriptionState = state;
        if (this.authBindings?.subscriptionStatus) {
            this.authBindings.subscriptionStatus.textContent = state.message;
            this.authBindings.subscriptionStatus.dataset.status = state.status;
        }
    }

    setButtonBusy(button, isBusy, busyLabel = 'Working...') {
        if (!button) return;
        if (isBusy) {
            button.dataset.originalText = button.textContent;
            button.textContent = busyLabel;
            button.classList.add('is-loading');
            button.disabled = true;
        } else {
            const original = button.dataset.originalText;
            if (original) {
                button.textContent = original;
                delete button.dataset.originalText;
            }
            button.classList.remove('is-loading');
            button.disabled = false;
        }
    }

    updateScrollProgress() {
        const scrollTop = window.scrollY;
        const documentHeight = document.documentElement.scrollHeight - window.innerHeight;
        this.scrollProgress = Math.min(scrollTop / Math.max(documentHeight, 1), 1);

        // Update 3D scene based on scroll
        if (this.currentConcept) {
            // Animate camera based on scroll
            this.animateCameraOnScroll();

            // If concept has onScroll method, call it
            if (this.currentConcept.onScroll) {
                this.currentConcept.onScroll(this.scrollProgress);
            }
        }

        // Animate 3D elements based on scroll position
        this.animateScroll3DElements();
    }

    animateCameraOnScroll() {
        if (!this.currentConcept || !this.camera) return;

        // Calculate camera rotation based on scroll
        // As user scrolls, camera rotates around the scene
        const maxRotationY = Math.PI * 0.5; // 90 degrees
        const rotationY = this.scrollProgress * maxRotationY;

        // Update camera position in a circular path
        const radius = 5;
        const cameraX = Math.sin(rotationY) * radius;
        const cameraZ = Math.cos(rotationY) * radius;
        const cameraY = 2 + this.scrollProgress * 1; // Slight vertical movement

        // Smoothly update camera
        this.camera.position.lerp(
            new THREE.Vector3(cameraX, cameraY, cameraZ),
            0.1
        );
        this.camera.lookAt(0, 0, 0);
    }

    animateScroll3DElements() {
        // Animate 3D elements based on scroll position
        this.scroll3DElements.forEach(element => {
            if (element.animate) {
                element.animate(this.scrollProgress);
            }
        });
    }

    setupControls() {
        this.isDragging = false;
        this.previousMousePosition = { x: 0, y: 0 };

        this.renderer.domElement.addEventListener('mousedown', (e) => {
            this.isDragging = true;
            this.previousMousePosition = { x: e.clientX, y: e.clientY };
        });

        this.renderer.domElement.addEventListener('mousemove', (e) => {
            if (this.isDragging && this.currentConcept) {
                const deltaX = e.clientX - this.previousMousePosition.x;
                const deltaY = e.clientY - this.previousMousePosition.y;
                this.currentConcept.onMouseMove(deltaX, deltaY);
                this.previousMousePosition = { x: e.clientX, y: e.clientY };
            }
        });

        this.renderer.domElement.addEventListener('mouseup', () => {
            this.isDragging = false;
        });

        // Allow natural page scrolling - wheel events scroll the page
        // 3D scene responds to scroll position instead of wheel events

        // Keyboard controls for concept-specific features
        window.addEventListener('keydown', (e) => {
            // Don't trigger if typing in an input field
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'BUTTON') {
                return;
            }
            if (this.currentConcept && this.currentConcept.onKeyPress) {
                this.currentConcept.onKeyPress(e.key);
            }
        });
    }


    loadConcept(conceptId) {
        // Only load Mirror Monitor concept (concept '1')
        if (conceptId !== '1') return;

        // Clean up previous concept
        if (this.currentConcept) {
            this.currentConcept.dispose();
        }

        // Remove all objects from scene (except lights)
        const objectsToRemove = [];
        this.scene.traverse((child) => {
            if (child !== this.scene && 
                child.type !== 'AmbientLight' && 
                child.type !== 'DirectionalLight') {
                objectsToRemove.push(child);
            }
        });
        objectsToRemove.forEach(obj => this.scene.remove(obj));

        // Create Mirror Monitor concept
        this.currentConcept = new Concept1MirrorMonitor(this.scene, this.camera, this.renderer);
    }

    onWindowResize() {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        // Maintain high pixel ratio for 4K
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 3));

        // Update water drop effect to cover entire window
        if (this.waterDropEffect) {
            // Update render target size
            if (this.waterDropEffect.sceneRenderTarget) {
                const pixelRatio = Math.min(window.devicePixelRatio, 3);
                const renderWidth = Math.floor(window.innerWidth * pixelRatio);
                const renderHeight = Math.floor(window.innerHeight * pixelRatio);
                this.waterDropEffect.sceneRenderTarget.setSize(renderWidth, renderHeight);
            }
            // Update geometry to cover entire viewport
            if (this.waterDropEffect.updateWaterMeshGeometry) {
                this.waterDropEffect.updateWaterMeshGeometry();
            }
        }

        if (this.currentConcept && this.currentConcept.onResize) {
            this.currentConcept.onResize();
        }
    }

    animate() {
        requestAnimationFrame(() => this.animate());

        const currentTime = performance.now();
        const deltaTime = (currentTime - this.lastTime) / 1000; // Convert to seconds
        this.lastTime = currentTime;

        // Update water drop effect
        if (this.waterDropEffect) {
            // Update water effect (handles materialization and fade-out)
            this.waterDropEffect.update(deltaTime);

            // Keep the captured scene in sync with camera movement for the entire
            // duration of the effect (including the brief fade-out), so that
            // there is no visible "jump" in camera position when the dim layer disappears.
            if (this.waterDropEffect.waterMesh && 
                this.waterDropEffect.waterMesh.visible && 
                !this.waterDropEffect.isComplete()) {
                this.waterDropEffect.renderSceneToTexture();
            }
        }

        if (this.currentConcept && this.currentConcept.update) {
            this.currentConcept.update();
        }

        // Render WebGL scene
        this.renderer.render(this.scene, this.camera);
    }
}

// Start app
new App();
